3	//! IPC subsystem — the heart of the MINIX microkernel.
4	//!
5	//! Slice 2.5 lights up the real IPC engine. `do_ipc` is the single SVC
6	//! entry point; it materializes mutable borrows of `PROC_TABLE` and
7	//! `PRIV_TABLE`, performs trap-mask gating, and dispatches to one of the
8	//! per-primitive handlers (`mini_send`, `mini_receive`, `mini_notify`,
9	//! `mini_senda`). The handlers operate on the explicit table slices —
10	//! they never touch the static directly — which keeps each primitive
11	//! testable in isolation and prevents the two-`&mut`-from-one-
12	//! `UnsafeCell` UB hazard that arises if each primitive re-borrows
13	//! individual slots.
14	//!
15	//! After every SVC, `el1_svc_tail` runs `schedule_next` to pick the
16	//! highest-priority runnable proc and flush any pending `MF_DELIVERMSG`
17	//! into its user buffer. That keeps the run queue honest when the caller
18	//! blocks (`rts_set` already dequeued it) and ensures a receiver that
19	//! got unblocked sees its message before resuming.
20	
21	mod deadlock;
22	mod message;
23	mod notify;
24	mod receive;
25	mod send;
26	mod senda;
27	
28	// User-buffer copy helpers — exposed to `crate::system` so the SYSTEM
29	// SENDREC fast path can read/write the request and reply without each
30	// caller dragging in `ipc::message` paths directly.
31	pub(crate) use message::{copy_msg_from_user, copy_msg_to_user};
32	pub(crate) use notify::deliver_ksig;
33	
34	use core::fmt::Write;
35	use core::sync::atomic::{AtomicU64, Ordering};
36	
37	use minixrs_kernel_shared::ProcNr;
38	use minixrs_kernel_shared::endpoint::{ANY, Endpoint};
39	use minixrs_kernel_shared::error::{EBADCALL, ECALLDENIED, ETRAPDENIED, OK};
40	use minixrs_kernel_shared::ipc_const::{NOTIFY, RECEIVE, SEND, SENDA, SENDNB, SENDREC};
41	
42	use crate::arch::ArchRegisterFrame;
43	use crate::proc::flags::{MF_DELIVERMSG, MF_REPLY_PEND};
44	use crate::proc::sched::{self, CURRENT_PROC_NR};
45	use crate::proc::table::{N_PROC_SLOTS, priv_table_mut_slice, proc_index, proc_table_mut_slice};
46	use crate::proc::{Priv, Proc};
47	use crate::uart::Uart;
48	
49	use receive::RecvFlags;
50	use send::SendFlags;
51	
52	/// Running total of IPC calls dispatched. Sampled at [`TRACE_EVERY`]
53	/// intervals for the boot-time observability trace.
54	static CALL_COUNT: AtomicU64 = AtomicU64::new(0);
55	
56	/// Cadence of the boot-time IPC trace. ~600 IPC ops/sec under the
57	/// slice-2.5 ping-pong demo → ~6 trace lines/sec; well under PL011's
58	/// ~290 lines/sec ceiling at 115200 baud.
59	///
60	/// TODO(phase 4): once servers come online and per-second IPC rate
61	/// jumps an order of magnitude, this needs to become a runtime knob
62	/// (DS_SUBSCRIBE-driven) or scale by load.
63	const TRACE_EVERY: u64 = 100;
64	
65	/// Number of leading SVCs to trace unconditionally, regardless of
66	/// [`TRACE_EVERY`]. Gives the early-boot output enough granularity to
67	/// show each stub's first IPC call — slice 2.6 added a third stub (C)
68	/// whose fast-path SENDRECs to SYSTEM outpace stubs A and B by orders
69	/// of magnitude, so without this aid the slice-2.5 ping-pong looks like
70	/// it regressed even though A↔B are still cooperating fine. Slice 4.5
71	/// widened 12 → 24: six boot servers' startup SENDRECs (GET_WHOAMI +
72	/// DS publish + replies + RS's first heartbeat round) exceed the old
73	/// window. PM itself boots after stub C's kernel-call flood begins, so
74	/// its handshake still lands past any practical head window — the
75	/// `[ksys SYS_PRIVCTL] target=E` trace is PM's boot evidence instead
76	/// (it can only fire after PM's GET_WHOAMI + DS publish succeeded).
77	const TRACE_HEAD: u64 = 24;
78	
79	/// IPC dispatch. Called from `trap.S` immediately after the SVC entry
80	/// stub has saved the caller's registers into `frame`.
81	///
82	/// Argument convention (mirrors MINIX 3 `kernel/proc.c:609 do_ipc`):
83	///
84	/// | reg | meaning                          |
85	/// |-----|----------------------------------|
86	/// | x0  | source/destination endpoint      |
87	/// | x1  | IPC primitive number             |
88	/// | x2  | pointer to the user's `Message`  |
89	/// | x3  | (SENDA only) table length        |
90	///
91	/// The result is written back into `frame.x[0]` — the SVC restore path
92	/// puts it in the caller's `x0` on `eret`.
93	#[unsafe(no_mangle)]
94	pub extern "C" fn do_ipc(frame: &mut ArchRegisterFrame) {
95	    let src_dst_e: Endpoint = frame.x[0] as i32;
96	    let call_nr: i32 = frame.x[1] as i32;
97	    let user_msg_va: u64 = frame.x[2];
98	    let extra: u64 = frame.x[3];
99	
100	    // SAFETY: SVC dispatch is single-threaded (DAIF.I masked at EL1); no
101	    // other code can write to PROC_TABLE/PRIV_TABLE before we return.
102	    let proc_table = unsafe { proc_table_mut_slice() };
103	    let priv_table = unsafe { priv_table_mut_slice() };
104	
105	    let cur_raw = CURRENT_PROC_NR.load(Ordering::Relaxed);
106	    let caller_nr = ProcNr::new(cur_raw);
107	
108	    let result = dispatch(
109	        proc_table,
110	        priv_table,
111	        caller_nr,
112	        call_nr,
113	        src_dst_e,
114	        user_msg_va,
115	        extra,
116	    );
117	
118	    frame.x[0] = result as u64;
119	
120	    let n = CALL_COUNT.fetch_add(1, Ordering::Relaxed) + 1;
121	    if n <= TRACE_HEAD || n.is_multiple_of(TRACE_EVERY) {
122	        let mut uart = Uart::new();
123	        let _ = writeln!(
124	            uart,
125	            "[ipc {n}] caller={caller_nr} call={call_nr} target={src_dst_e:#x} result={result}",
126	        );
127	    }
128	}
129	
130	fn dispatch(
131	    proc_table: &mut [Proc; N_PROC_SLOTS],
132	    priv_table: &mut [Priv; NR_SYS_PROCS],
133	    caller_nr: ProcNr,
134	    call_nr: i32,
135	    src_dst_e: Endpoint,
136	    user_msg_va: u64,
137	    extra: u64,
138	) -> i32 {
139	    // Permission gate: caller must have a priv slot whose trap_mask
140	    // permits this primitive. Mirrors MINIX 3 `do_sync_ipc:562-568`.
141	    let Some(caller_idx) = proc_index(caller_nr) else {
142	        return EBADCALL;
143	    };
144	    let Some(caller_priv_id) = proc_table[caller_idx].priv_id else {
145	        return ECALLDENIED;
146	    };
147	    let trap_mask = priv_table[caller_priv_id.as_usize()].trap_mask;
148	    // ANY-source endpoint is only legal as a RECEIVE filter.
149	    if src_dst_e == ANY && call_nr != RECEIVE {
150	        return EBADCALL;
151	    }
152	    // Match on call_nr first so unknown primitives return EBADCALL.
153	    // Each arm gates on its own trap_mask bit so a valid-but-denied
154	    // primitive returns ETRAPDENIED. Keeps error precedence stable as
155	    // new primitives are added (no risk of an out-of-range call_nr
156	    // sneaking past the range check and getting ETRAPDENIED from a
157	    // stale `1 << call_nr` shift).
158	    match call_nr {
159	        SEND => trap_gate(trap_mask, SEND, || {
160	            send::mini_send(
161	                proc_table,
162	                priv_table,
163	                caller_nr,
164	                src_dst_e,
165	                user_msg_va,
166	                SendFlags::Blocking,
167	            )
168	        }),
169	        RECEIVE => trap_gate(trap_mask, RECEIVE, || {
170	            receive::mini_receive(
171	                proc_table,
172	                priv_table,
173	                caller_nr,
174	                src_dst_e,
175	                user_msg_va,
176	                RecvFlags::Blocking,
177	            )
178	        }),
179	        SENDREC => trap_gate(trap_mask, SENDREC, || {
180	            // Fast-path: SENDREC to the SYSTEM endpoint never enters mini_send.
181	            // MINIX 3 `proc.c::do_ipc` does the same divert — SYSTEM has no
182	            // scheduler context, so a real send would block forever.
183	            if src_dst_e == crate::system::system_endpoint() {
184	                crate::system::kernel_call_sendrec(proc_table, priv_table, caller_nr, user_msg_va)
185	            } else {
186	                do_sendrec(proc_table, priv_table, caller_nr, src_dst_e, user_msg_va)
187	            }
188	        }),
189	        NOTIFY => trap_gate(trap_mask, NOTIFY, || {
190	            notify::mini_notify(proc_table, priv_table, caller_nr, src_dst_e)
191	        }),
192	        SENDNB => trap_gate(trap_mask, SENDNB, || {
193	            send::mini_send(
194	                proc_table,
195	                priv_table,
196	                caller_nr,
197	                src_dst_e,
198	                user_msg_va,
199	                SendFlags::NonBlocking,
200	            )
201	        }),
202	        SENDA => trap_gate(trap_mask, SENDA, || {
203	            senda::mini_senda(
204	                proc_table,
205	                priv_table,
206	                caller_nr,
207	                user_msg_va,
208	                extra as usize,
209	            )
210	        }),
211	        _ => EBADCALL,
212	    }
213	}
214	
215	/// Permission gate: returns `ETRAPDENIED` if the caller's `trap_mask`
216	/// doesn't permit `call_nr`, otherwise runs `f` and returns its result.
217	///
218	/// The shift is done in `u32` to dodge two pitfalls: (a) `1u16 <<
219	/// SENDA(16)` panics in debug builds and wraps to 0 in release, and (b)
220	/// every caller funnels through the match in `dispatch`, so `call_nr`
221	/// is one of the IPC primitive constants — but the explicit u32 widen
222	/// makes the gate robust to future re-use.
223	///
224	/// TODO(slice 2.6+): widen `Priv::trap_mask` from `u16` to `u32` to
225	/// match MINIX 3's `unsigned int` so SENDA's bit (16) actually fits.
226	/// Until then SENDA is dispatcher-denied here even though
227	/// `mini_senda` would otherwise reply `ENOSYS` — see the note on
228	/// `senda::mini_senda`.
229	#[inline]
230	fn trap_gate(trap_mask: u16, call_nr: i32, f: impl FnOnce() -> i32) -> i32 {
231	    let bit = 1u32.wrapping_shl(call_nr as u32);
232	    if (trap_mask as u32) & bit == 0 {
233	        return ETRAPDENIED;
234	    }
235	    f()
236	}
237	
238	/// `SENDREC` is the atomic-send-then-receive primitive used by every
239	/// `_syscall()` wrapper. SEND half blocks (or delivers); on success we
240	/// mark `MF_REPLY_PEND` and run the RECEIVE half against the same partner.
241	fn do_sendrec(
242	    proc_table: &mut [Proc; N_PROC_SLOTS],
243	    priv_table: &mut [Priv; NR_SYS_PROCS],
244	    caller_nr: ProcNr,
245	    dst_e: Endpoint,
246	    user_msg_va: u64,
247	) -> i32 {
248	    let send_result = send::mini_send(
249	        proc_table,
250	        priv_table,
251	        caller_nr,
252	        dst_e,
253	        user_msg_va,
254	        SendFlags::Blocking,
255	    );
256	    if send_result != OK {
257	        return send_result;
258	    }
259	    let Some(caller_idx) = proc_index(caller_nr) else {
260	        return EBADCALL;
261	    };
262	    proc_table[caller_idx].misc_flags |= MF_REPLY_PEND;
263	    receive::mini_receive(
264	        proc_table,
265	        priv_table,
266	        caller_nr,
267	        dst_e,
268	        user_msg_va,
269	        RecvFlags::Blocking,
270	    )
271	}
272	
273	/// Copy a pending IPC message out to the user buffer recorded at
274	/// RECEIVE-time and clear `MF_DELIVERMSG`. Called from
275	/// `sched::schedule_next` on every EL1 → EL0 transition.
276	pub fn flush_deliver_msg(p: &mut Proc) {
277	    if p.misc_flags & MF_DELIVERMSG == 0 {
278	        return;
279	    }
280	    // Best-effort; if the user buffer is bad, slice 2.5 has no place to
281	    // signal that (the receiver hasn't returned yet). Phase 3 adds
282	    // MF_MSGFAILED + signal delivery to handle this. The bounds check
283	    // in `copy_msg_to_user` keeps an out-of-range VA from faulting EL1.
284	    let _ = message::copy_msg_to_user(p.deliver_msg_vir, &p.deliver_msg);
285	    p.misc_flags &= !MF_DELIVERMSG;
286	}
287	
288	/// Kernel-originated page-fault notification: send `VM_PAGEFAULT` to the VM
289	/// server on behalf of `faulting_nr`. Called from the EL1 page-fault handler
290	/// (`arch::aarch64::exception::do_page_fault`) after it has recorded the fault
291	/// state and set `RTS_PAGEFAULT` on the faulter.
292	///
293	/// Materializes the proc-table slice here (the page-fault handler otherwise
294	/// works through `current_proc_mut`), keeping the "only `ipc` materializes the
295	/// table for the primitives" discipline intact.
296	pub fn send_pagefault_to_vm(faulting_nr: ProcNr, far: u64, flags: u32) {
297	    // SAFETY: EL1 page-fault context — single-threaded, DAIF.I masked. The
298	    // record/`rts_set` borrow in `do_page_fault` has already ended, so no other
299	    // PROC_TABLE reference is live.
300	    let proc_table = unsafe { proc_table_mut_slice() };
301	    send::mini_pf_send(proc_table, faulting_nr, far, flags);
302	}
303	
304	/// Kernel-originated `SCHEDULING_NO_QUANTUM` notification: send it to
305	/// `scheduler_e` on behalf of the preempted proc `preempted_nr` (slice 4.3).
306	/// Called from `proc::sched::reschedule` after it has dequeued the preempted
307	/// proc and left `RTS_NO_QUANTUM` set.
308	///
309	/// Materializes the proc-table slice here (reschedule otherwise works through
310	/// `proc_slot_mut`), keeping the "only `ipc` materializes the table for the
311	/// primitives" discipline intact — exactly like [`send_pagefault_to_vm`].
312	pub fn send_no_quantum(preempted_nr: ProcNr, scheduler_e: Endpoint) {
313	    // SAFETY: IRQ/reschedule context — single-threaded, DAIF.I masked. The
314	    // `cur` borrow in `reschedule` has already ended, so no other PROC_TABLE
315	    // reference is live.
316	    let proc_table = unsafe { proc_table_mut_slice() };
317	    send::mini_sched_no_quantum_send(proc_table, preempted_nr, scheduler_e);
318	}
319	
320	/// Cadence of the boot-time alarm-fire trace.
321	const ALARM_TRACE_EVERY: u64 = 100;
322	/// Leading alarm fires to trace unconditionally (head carve-out), so RS's first
323	/// few periodic fires show even though stub C's `SYS_GETINFO` flood dwarfs the
324	/// modulo sampler (same reasoning as [`TRACE_HEAD`] / `sched::NOQ_TRACE_HEAD`).
325	const ALARM_TRACE_HEAD: u64 = 6;
326	/// Count of alarm fires, for the head/modulo trace above.
327	static ALARM_COUNT: AtomicU64 = AtomicU64::new(0);
328	
329	/// Fire every per-proc one-shot alarm due at or before `now` (slice 4.4).
330	///
331	/// Called from `clock::tick` *only* when the `EARLIEST_ALARM` fast-path gate
332	/// says an alarm is due, so the O(N) proc-table scan is paid rarely. For each
333	/// expired [`Proc::alarm_at`] it clears the field, delivers a kernel-originated
334	/// `NOTIFY` from `CLOCK` to the owner ([`notify::deliver_alarm`]), and traces
335	/// the fire; it then recomputes the minimum of the still-armed deadlines and
336	/// writes it back into the clock gate via [`crate::clock::set_earliest_alarm`].
337	///
338	/// Materializes the proc/priv slices here — same "only `ipc` materializes the
339	/// tables for delivery" discipline as [`send_pagefault_to_vm`] /
340	/// [`send_no_quantum`].
341	///
342	/// [`Proc::alarm_at`]: crate::proc::Proc::alarm_at
343	pub fn fire_expired_alarms(now: u64) {
344	    // SAFETY: IRQ/clock context — single-threaded, DAIF.I masked. `clock::tick`
345	    // has taken no PROC_TABLE/PRIV_TABLE borrow before calling us.
346	    let proc_table = unsafe { proc_table_mut_slice() };
347	    let priv_table = unsafe { priv_table_mut_slice() };
348	
349	    let mut next_earliest: u64 = 0;
350	    for idx in 0..N_PROC_SLOTS {
351	        let at = proc_table[idx].alarm_at;
352	        if at == 0 {
353	            continue; // disarmed slot
354	        }
355	        if at > now {
356	            next_earliest = fold_earliest(next_earliest, at); // armed but not yet due
357	            continue;
358	        }
359	        // Due: disarm, deliver the CLOCK notification, trace the fire.
360	        proc_table[idx].alarm_at = 0;
361	        notify::deliver_alarm(proc_table, priv_table, idx);
362	        trace_alarm_fire(proc_table[idx].name[0], proc_table[idx].nr, now);
363	    }
364	
365	    crate::clock::set_earliest_alarm(next_earliest);
366	}
367	
368	/// Fold one still-armed deadline `at` into the running next-earliest, treating
369	/// 0 as "none". Pulled out of [`fire_expired_alarms`] to keep that scan flat.
370	fn fold_earliest(current: u64, at: u64) -> u64 {
371	    if current == 0 || at < current {
372	        at
373	    } else {
374	        current
375	    }
376	}
377	
378	/// Emit the head/modulo-sampled `[alarm N]` fire trace. Bumps the fire counter
379	/// and prints only on the head carve-out or every [`ALARM_TRACE_EVERY`]th fire
380	/// — kept out of [`fire_expired_alarms`] so its scan stays under the cognitive-
381	/// complexity bar.
382	fn trace_alarm_fire(name0: u8, nr: ProcNr, now: u64) {
383	    let n = ALARM_COUNT.fetch_add(1, Ordering::Relaxed) + 1;
384	    if n > ALARM_TRACE_HEAD && !n.is_multiple_of(ALARM_TRACE_EVERY) {
385	        return;
386	    }
387	    let id = if name0 != 0 { name0 } else { b'?' };
388	    let _ = writeln!(
389	        Uart::new(),
390	        "[alarm {n}] owner={} nr={} at={now}",
391	        id as char,
392	        nr.get()
393	    );
394	}
395	
396	/// SVC-tail shim. `trap.S` calls this between `do_ipc` and
397	/// `el1_return_to_user`; it picks the next runnable proc (which may be
398	/// the same caller, may be a higher-priority receiver that just
399	/// unblocked, or may be someone else entirely if the caller blocked)
400	/// and flushes any pending message into the new current proc's user
401	/// buffer.
402	#[unsafe(no_mangle)]
403	pub extern "C" fn el1_svc_tail() {
404	    // SAFETY: SVC dispatch context — single-threaded, DAIF.I masked,
405	    // no other PROC_TABLE/RUNQ references live at this point.
406	    unsafe { sched::schedule_next() }
407	}
408	
409	// ---------------------------------------------------------------------------
410	// Re-exported / locally needed `kernel_shared` items.
411	// ---------------------------------------------------------------------------
412	
413	use minixrs_kernel_shared::com::NR_SYS_PROCS;
414

